#include <stdarg.h>

void abort(void);
void exit(int);

double f(float f1, float f2, float f3, float f4, float f5, float f6, ...) {
  va_list ap;
  double  d;

  va_start(ap, f6);
  d = va_arg(ap, double);
  va_end(ap);
  return d;
}

int main() {
  if (f(1, 2, 3, 4, 5, 6, 7.0) != 7.0)
    abort();
  exit(0);
}


